#!/bin/sh
# Fabrique les scripts à coller dans Supabase :
#  - RESET_ALPHA_3_0.sql : efface tout (comptes compris) puis installe le schéma complet (3.0 + mises à jour) ;
#  - MAJ_ALPHA_3_2.sql : met à jour une base 3.0 à 3.1 sans rien effacer (contient la 3.0.1, la 3.0.2 et la 3.1).
cd "$(dirname "$0")"
rm -f MAJ_ALPHA_3_0_1.sql MAJ_ALPHA_3_0_2.sql MAJ_ALPHA_3_1.sql
{ cat reset_entete.sql; echo; cat schema.sql; echo; cat alpha_3_0_1.sql; echo; cat alpha_3_0_2.sql; echo; cat alpha_3_1.sql; echo; cat alpha_3_2.sql; echo; cat alpha_3_2_1.sql; echo; cat alpha_3_2_4.sql; echo; cat alpha_3_3.sql; echo; cat alpha_3_3_2.sql; echo; cat alpha_3_4.sql; echo; cat alpha_3_4_1.sql; echo; cat alpha_3_4_2.sql; echo; echo "select 'Pocket Club alpha 3.4.2 installé : base vide, crée ton compte dans l''application.' as resultat;"; } > RESET_ALPHA_3_0.sql
{ echo "-- MAJ_ALPHA_3_2.sql · Pocket Club · à lancer une fois dans Supabase > SQL Editor > Run."; echo "-- Met à jour la base (3.0 à 3.1) sans effacer de données. Contient la 3.0.1, la 3.0.2 et la 3.1. Peut être relancé sans risque."; echo; cat alpha_3_0_1.sql; echo; cat alpha_3_0_2.sql; echo; cat alpha_3_1.sql; echo; cat alpha_3_2.sql; echo; echo "select 'Pocket Club alpha 3.2 : mise à jour faite.' as resultat;"; } > MAJ_ALPHA_3_2.sql
{ echo "-- MAJ_ALPHA_3_2_1.sql · Pocket Club · à lancer une fois dans Supabase > SQL Editor > Run (après la 3.2)."; echo "-- Ajoute les vidéos des exercices, sans effacer de données. Peut être relancé sans risque."; echo; cat alpha_3_2_1.sql; echo; echo "select 'Pocket Club alpha 3.2.1 : vidéos des exercices prêtes.' as resultat;"; } > MAJ_ALPHA_3_2_1.sql
{ echo "-- MAJ_ALPHA_3_2_4.sql · Pocket Club · à lancer une fois dans Supabase > SQL Editor > Run (après la 3.2)."; echo "-- Contient la 3.2.1 (vidéos des exercices) et la 3.2.4 (séries, retrait de la fonction événements et buvette), sans effacer de données. Peut être relancé sans risque."; echo; cat alpha_3_2_1.sql; echo; cat alpha_3_2_4.sql; echo; echo "select 'Pocket Club alpha 3.2.4 : mise à jour faite.' as resultat;"; } > MAJ_ALPHA_3_2_4.sql
{ echo "-- MAJ_ALPHA_3_3.sql · Pocket Club · étape B 2 sur 5 (notifications) · à lancer une fois dans Supabase > SQL Editor > Run (après la 3.2.4)."; echo "-- Ajoute les téléphones inscrits et la file des notifications, sans effacer de données. Peut être relancé sans risque."; echo; cat alpha_3_3.sql; echo; echo "select 'Pocket Club alpha 3.3 : notifications prêtes côté base (étape 2 sur 5).' as resultat;"; } > MAJ_ALPHA_3_3.sql
{ echo "-- MAJ_ALPHA_3_3_2.sql · Pocket Club · étape B 4 sur 5 (envoi automatique des notifications) · à lancer une fois dans Supabase > SQL Editor > Run (après la 3.3)."; echo "-- Remplacer METS_ICI_PUSH_SECRET par le mot de passe PUSH_SECRET avant de lancer. Sans perte de données, relançable sans risque."; echo; cat alpha_3_3_2.sql; echo; echo "select 'Pocket Club alpha 3.3.2 : envoi automatique en place (étape 4 sur 5).' as resultat, (select secret <> 'METS_ICI_PUSH_SECRET' from push_settings) as mot_de_passe_enregistre;"; } > MAJ_ALPHA_3_3_2.sql
{ echo "-- MAJ_ALPHA_3_4.sql · Pocket Club · convocations inter-clubs · à lancer une fois dans Supabase > SQL Editor > Run (après la 3.3.2)."; echo "-- Ajoute « Nous recevons » sur les matchs et les données des convocations, sans effacer de données. Peut être relancé sans risque."; echo; cat alpha_3_4.sql; echo; echo "select 'Pocket Club alpha 3.4 : convocations prêtes.' as resultat;"; } > MAJ_ALPHA_3_4.sql
{ echo "-- MAJ_ALPHA_3_4_1.sql · Pocket Club · n° 59 à 68 · à lancer une fois dans Supabase > SQL Editor > Run (après la 3.4)."; echo "-- Sans perte de données, relançable sans risque."; echo; cat alpha_3_4_1.sql; echo; echo "select 'Pocket Club alpha 3.4.1 : mise à jour faite.' as resultat;"; } > MAJ_ALPHA_3_4_1.sql
{ echo "-- MAJ_ALPHA_3_4_2.sql · Pocket Club · n° 69 à 74 · à lancer une fois dans Supabase > SQL Editor > Run (après la 3.4.1)."; echo "-- Sans perte de données, relançable sans risque."; echo; cat alpha_3_4_2.sql; echo; echo "select 'Pocket Club alpha 3.4.2 : mise à jour faite.' as resultat;"; } > MAJ_ALPHA_3_4_2.sql
